import React from "react";
import "../styles/timeline.css";

export default function TimelineViewer({ timeline }) {
  if (!timeline) return null;

  return (
    <div className="timeline-box">
      <h3>📌 Jira + GitHub PR Timeline</h3>

      <p><b>Issue:</b> {timeline.issue.key} — {timeline.issue.summary}</p>

      <p>
        <b>PR:</b> #{timeline.pr.number} — {timeline.pr.title}
        &nbsp;(<a href={timeline.pr.html_url} target="_blank">Open PR</a>)
      </p>

      <h4>🔽 Timeline Events</h4>

      {timeline.timeline.map((event, idx) => (
        <div key={idx} className="timeline-event">
          <b>{event.type.toUpperCase()}</b> — {event.timestamp}<br/>
          👤 {event.actor}<br/>
          📝 {event.message}

          {event.time_to_next_review_readable && (
            <p>⏳ Next Review: {event.time_to_next_review_readable}</p>
          )}

          {event.time_to_next_commit_readable && (
            <p>⏳ Next Commit: {event.time_to_next_commit_readable}</p>
          )}
        </div>
      ))}

      <h4>🔁 Rework Cycles: {timeline.reworkCycles}</h4>
    </div>
  );
}
